import{_ as a,o,c as i,ag as t}from"./chunks/framework.CrXGS008.js";const c=JSON.parse('{"title":"Tunele","description":"","frontmatter":{},"headers":[],"relativePath":"pl/car-wash/tunnels.md","filePath":"pl/car-wash/tunnels.md"}'),n={name:"pl/car-wash/tunnels.md"};function r(l,e,s,z,d,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="tunele" tabindex="-1">Tunele <a class="header-anchor" href="#tunele" aria-label="Permalink to &quot;Tunele&quot;">​</a></h1><p>Tunel to wjazd, przy którym kierowca się zatrzymuje, linia, po której jedzie pojazd, oraz rozmieszczone wzdłuż niej łuki, szczotki i suszarka. Dwa tunele są gotowe do użycia: <strong>Strawberry</strong> i <strong>Little Seoul</strong>.</p><h2 id="przebieg-mycia" tabindex="-1">Przebieg mycia <a class="header-anchor" href="#przebieg-mycia" aria-label="Permalink to &quot;Przebieg mycia&quot;">​</a></h2><ol><li>Kierowca zatrzymuje się przy wjeździe, przodem do wyjazdu. Podpowiedź pokazuje najniższą cenę.</li><li><strong>E</strong> otwiera menu mycia z programami i ich cenami (z uwzględnieniem zniżek dla zawodów i procentu ceny tunelu).</li><li>Cena zostaje pobrana, a pojazd jest prowadzony wzdłuż linii: piana, szczotki, płukanie, suszarka, zależnie od programu. Wszyscy w pobliżu widzą to samo mycie.</li><li>Na wyjeździe pojazd jest czysty, a jeśli program obejmuje wosk, także nawoskowany.</li></ol><p>Wjazd odmawia mycia, gdy:</p><ul><li>tunel jest już zajęty (jeden pojazd naraz);</li><li>pojazd stoi w złym kierunku;</li><li>inny pojazd blokuje przejazd;</li><li>klasa pojazdu jest zablokowana albo pojazd jest za szeroki (<code>BlockedClasses</code>, <code>MaxVehicleWidth</code>);</li><li>pojazd jest już czysty, a <code>RequireDirt</code> jest włączone;</li><li>gracza nie stać na zapłatę.</li></ul><h2 id="edytor-tuneli" tabindex="-1">Edytor tuneli <a class="header-anchor" href="#edytor-tuneli" aria-label="Permalink to &quot;Edytor tuneli&quot;">​</a></h2><p>Otwórz go komendą <code>/nay:carwash</code> albo przyciskiem <strong>Zarządzaj tunelami</strong> na stronie Car Wash w <code>/nay</code>. Wymaga scope&#39;a <code>nay_car_wash.config</code>.</p><p>Menedżer wyświetla listę tuneli: możesz przejść do tunelu, edytować go, otworzyć lub zamknąć albo usunąć. Aby dodać nowy:</p><ol><li><p><strong>Utwórz tutaj</strong>: stań przy wjeździe, przodem do wyjazdu. Albo <strong>Kopiuj</strong> jedną z myjni z podstawowej wersji gry.</p></li><li><p>Wybierz element (wjazd, początek i koniec linii, łuki, szczotki, suszarka) i przesuń go przyciskami lub klawiaturą:</p><ul><li>strzałki: do przodu, do tyłu, w lewo, w prawo wzdłuż przejazdu;</li><li>Page Up / Page Down: wysokość;</li><li>Q / E: obrót;</li><li>Tab: następny element.</li></ul><p>Do precyzyjnych poprawek dostępne są trzy wielkości kroku.</p></li><li><p><strong>Do mojej pozycji</strong> i <strong>Na ziemię</strong> ustawiają wybrany element. <strong>Chodź</strong> (G) uwalnia mysz, aby móc się poruszać i rozglądać. Naciśnij ponownie G, aby wrócić do panelu.</p></li><li><p><strong>Zapisz tunel</strong>. Tunel od razu działa dla wszystkich graczy.</p></li></ol><p>Edytor wypełnia ustawienie <code>Tunnels</code>. Jego pola opisuje strona <a href="/pl/car-wash/settings#tunele">Ustawienia</a>.</p>',11)])])}const y=a(n,[["render",r]]);export{c as __pageData,y as default};
